/**
 * 周报生成纯函数单测（B18）。
 * 直接测：周日期工具 / 空数据兜底 / 确定性规则生成。
 * service 层逻辑已通过 tsc 验证，此处重点测可独立的确定性规则。
 */
declare function toYMD(d: Date): string;
/** 获取指定日期所在周的周一（UTC 00:00） */
declare function getMondayOfWeek(date: Date): Date;
/** 保留 n 位小数 */
declare function roundTo(n: number, digits: number): number;
interface TaskRow {
    id: string;
    status: string;
    assigneeId: string | null;
    dueAt: string | null;
    createdAt: string;
    completedAt: string | null;
    estimatedHours: number | null;
}
interface TimeRow {
    taskId: string;
    userId: string;
    durationSeconds: number | null;
}
/**
 * 确定性周报生成（纯函数版，供单测）。
 * 与 reports.service.ts generateWeeklyReport 内部逻辑保持一致。
 */
declare function generateWeeklyReport(tasks: TaskRow[], timeEntries: TimeRow[], weekStart: Date): {
    summary: {
        totalTasks: number;
        completedTasks: number;
        cancelledTasks: number;
        newTasks: number;
        overdueTasks: number;
        totalActualHours: number;
        totalEstimatedHours: number;
        completionRate: number;
        onTimeRate: number | null;
    };
    highlights: string[];
    risks: string[];
};
